import React, { useState, useEffect } from 'react';
import { createUser, getUsers, deleteUser, updateUser } from '../services/api';
import { getFranchises } from '../services/api';
import { Button, TextField, Grid, Box, Typography, Paper, Select, MenuItem } from '@mui/material';

const CreateUser = () => {
  const [formData, setFormData] = useState({
    username: '',
    password: '',
    name: '',
    role: 'user',
    franchiseId: '',
  });

  const [franchises, setFranchises] = useState([]);
  const [users, setUsers] = useState([]);
  const [editingUser, setEditingUser] = useState(null);

  useEffect(() => {
    const fetchFranchises = async () => {
      try {
        const response = await getFranchises();
        setFranchises(response.data);
      } catch (error) {
        alert('Error fetching franchises: ' + (error.response?.data?.message || error.message));
      }
    };

    const fetchUsers = async () => {
      try {
        const response = await getUsers();
        setUsers(response);
      } catch (error) {
        alert('Error fetching users: ' + (error.response?.data?.message || error.message));
      }
    };

    fetchFranchises();
    fetchUsers();
  }, []);

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    try {
      if (editingUser) {
        await updateUser(editingUser._id, formData);
        alert('User updated successfully!');
      } else {
        await createUser(formData);
        alert('User created successfully!');
      }

      setEditingUser(null);
      setFormData({ username: '', password: '', name: '', role: 'user', franchiseId: '' });

      const response = await getUsers();
      setUsers(response);
    } catch (error) {
      alert('Error creating/updating user: ' + (error.response?.data?.message || error.message));
    }
  };

  const handleEdit = (user) => {
    setEditingUser(user);
    setFormData({
      username: user.username,
      password: '', 
      name: user.name,
      role: user.role,
      franchiseId: user.franchiseId || '',
    });
  };

  const handleDelete = async (userId) => {
    try {
      await deleteUser(userId);
      alert('User deleted successfully!');
      const response = await getUsers();
      setUsers(response);
    } catch (error) {
      console.error("Failed to delete user:", error.message);
      alert('Failed to delete user. Please try again.');
    }
  };

  return (
    <Box sx={{ p: 3 }}>
      <Typography variant="h4" sx={{ fontWeight: 'bold', marginBottom: 3 }}>
        {editingUser ? 'Edit User' : 'Create User'}
      </Typography>

      <Paper sx={{ padding: 3 }}>
        <form onSubmit={handleSubmit}>
          <Grid container spacing={2}>
            <Grid item xs={12}>
              <TextField
                label="Username"
                name="username"
                value={formData.username}
                onChange={handleChange}
                fullWidth
                required
                variant="outlined"
              />
            </Grid>
            <Grid item xs={12}>
              <TextField
                label="Password"
                name="password"
                type="password"
                value={formData.password}
                onChange={handleChange}
                fullWidth
                required={!editingUser}
                variant="outlined"
              />
            </Grid>
            <Grid item xs={12}>
              <TextField
                label="Full Name"
                name="name"
                value={formData.name}
                onChange={handleChange}
                fullWidth
                required
                variant="outlined"
              />
            </Grid>
            <Grid item xs={12} sm={6}>
              <Select
                label="Role"
                name="role"
                value={formData.role}
                onChange={handleChange}
                fullWidth
                variant="outlined"
              >
                <MenuItem value="user">User</MenuItem>
                <MenuItem value="admin">Admin</MenuItem>
              </Select>
            </Grid>
            <Grid item xs={12} sm={6}>
              <Select
                label="Franchise"
                name="franchiseId"
                value={formData.franchiseId}
                onChange={handleChange}
                fullWidth
                required
                variant="outlined"
              >
                <MenuItem value="">Select a Franchise</MenuItem>
                {franchises.map((franchise) => (
                  <MenuItem key={franchise._id} value={franchise._id}>
                    {franchise.name} - {franchise.location}
                  </MenuItem>
                ))}
              </Select>
            </Grid>
            <Grid item xs={12}>
              <Button type="submit" variant="contained" color="primary" sx={{ width: '100%' }}>
                {editingUser ? 'Update User' : 'Create User'}
              </Button>
            </Grid>
          </Grid>
        </form>
      </Paper>

      <Typography variant="h5" sx={{ marginTop: 4, marginBottom: 2 }}>
        All Users
      </Typography>
      <Paper sx={{ padding: 3 }}>
        <Grid container spacing={2}>
          {users.map((user) => {
            const franchiseName = user.franchise ? user.franchise.name : 'N/A';
            return (
              <Grid item xs={12} key={user._id}>
                <Paper sx={{ padding: 2, marginBottom: 2, display: 'flex', justifyContent: 'space-between' }}>
                  <Box>
                    <Typography variant="h6">{user.username}</Typography>
                    <Typography variant="body2">{user.name}</Typography>
                    <Typography variant="body2">{user.role}</Typography>
                    <Typography variant="body2">{franchiseName}</Typography>
                  </Box>
                  <Box>
                    <Button
                      variant="outlined"
                      color="primary"
                      onClick={() => handleEdit(user)}
                      sx={{ marginRight: 1 }}
                    >
                      Edit
                    </Button>
                    <Button
                      variant="outlined"
                      color="error"
                      onClick={() => handleDelete(user._id)}
                    >
                      Delete
                    </Button>
                  </Box>
                </Paper>
              </Grid>
            );
          })}
        </Grid>
      </Paper>
    </Box>
  );
};

export default CreateUser;
